// ─────────────────────────────────────────────────────────────────────
// VoiceOps — central configuration.
// Every workflow calls this sub-workflow first ("Load config"), so a
// campaign, CRM field or provider is changed in exactly one place.
// Secrets are read from environment variables, never stored here.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try { return $env[key] ?? fallback; } catch (e) { return fallback; }  // $env may be blocked on some hosts
};

const CONFIG = {
  crm: {
    provider: env('CRM_PROVIDER', 'zoho'),              // 'zoho' | 'hubspot' | 'generic'
    base_url: env('CRM_BASE_URL', 'https://www.zohoapis.eu'),
    contact_module: 'Contacts',                         // Zoho module holding the people you call (Contacts, Leads, Accounts…)
    activity_module: 'Calls',                           // where every call attempt is logged
    link_field: 'Who_Id',                               // Zoho: Who_Id for Contacts/Leads, What_Id for Accounts/Deals
    fields: {                                           // canonical name → your CRM's API field name
      outcome: 'AI_Call_Outcome',
      summary: 'AI_Call_Summary',
      campaign_key: 'AI_Campaign',                      // HubSpot/generic only (Zoho encodes it in Subject)
      campaign_run: 'AI_Campaign_Run',
      contact_ref: 'AI_Contact_Ref',
    },
  },

  voice: {
    base_url: env('VOICE_API_BASE_URL', 'https://api.elevenlabs.io'),  // use your data-residency host if any
    phone_number_id: env('VOICE_PHONE_NUMBER_ID', 'REPLACE_ME'),
    conversation_url_template: 'https://elevenlabs.io/app/conversational-ai/history/{conversation_id}',
  },

  webhooks: {
    voice_signing_secret: env('VOICE_WEBHOOK_SECRET', ''),  // HMAC secret of the post-call webhook
    max_age_secs: 1800,                                     // replay protection window
  },

  safety_net: {
    initial_delay_minutes: 20,   // first look after a batch is submitted
    poll_every_minutes: 10,      // then poll the batch until it has finished dialling
    max_polls: 12,
    grace_minutes: 5,            // leave late webhooks time to land before declaring silence
  },

  alerts: { webhook_url: env('ALERT_WEBHOOK_URL', '') },   // Slack/Teams incoming-webhook compatible
  kpi: { ingest_url: env('KPI_INGEST_URL', ''), lookback_days: 14 },

  qa: {
    sheet_id: env('QA_SHEET_ID', 'REPLACE_ME'),
    gateway_token: env('QA_GATEWAY_TOKEN', ''),
    model: env('QA_MODEL', 'claude-sonnet-5'),
    max_tokens: 6000,
    price_per_mtok: { input: null, output: null, cache_read: null, cache_write: null }, // fill in to track cost
    filters: { min_duration_secs: 45, min_messages: 6 },
  },

  workflows: { outcome_handler: 'vopsOutcome00000' },

  defaults: {
    outcome_keys: { outcome: 'call_outcome', scheduled_datetime: 'scheduled_datetime_iso', refusal_reason: 'refusal_reason' },
    outcome_aliases: { no_answer: 'no_answer', 'no-answer': 'no_answer', callback: 'callback_requested', declined: 'refused' },
    outcome_labels: {
      booked: 'Booked', booking_failed: 'Booking failed', refused: 'Refused', voicemail: 'Voicemail',
      no_answer: 'No answer', failed: 'Failed', callback_requested: 'Callback requested',
      confirmed: 'Confirmed', completed: 'Completed',
    },
  },

  // ── Campaigns ──────────────────────────────────────────────────────
  // key = what the CRM trigger sends as campaign_key
  campaigns: {
    no_show_recovery: {
      label: 'No Show Recovery',                // prefix of every run name / CRM activity subject
      agent_id: env('AGENT_NO_SHOW', 'REPLACE_ME'),
      timezone: 'Europe/London', locale: 'en-GB', default_country_code: '44',
      booking: { enabled: true, event_type_uri: 'https://api.calendly.com/event_types/REPLACE_ME', lookahead_days: 7, max_slots_offered: 12 },
      ab_test: { enabled: true, treatment_pct: 50, salt: 'nsr-2026', crm_field: 'AB_Tests', multi_select: true,
                 labels: { treatment: 'No Show Recovery - AI called', control: 'No Show Recovery - control' } },
      eligibility: null,
      retry: { enabled: true, retry_on: ['Voicemail', 'No answer', 'Failed'], max_retries: 1, delay_minutes: 180 },
      kpi: { enabled: true, success_outcomes: ['booked'], realization: { field: 'Session_Attended', truthy: ['Yes', true] } },
    },

    missing_documents: {
      label: 'Missing Documents',
      agent_id: env('AGENT_MISSING_DOCS', 'REPLACE_ME'),
      timezone: 'Europe/London', locale: 'en-GB', default_country_code: '44',
      booking: { enabled: false },
      ab_test: { enabled: true, treatment_pct: 50, salt: 'docs-2026', crm_field: 'AB_Tests', multi_select: true,
                 labels: { treatment: 'Missing Docs - AI called', control: 'Missing Docs - control' } },
      eligibility: {                               // re-checked live right before EVERY call
        status_field: 'Onboarding_Stage',
        allowed_statuses: ['Documents Missing'],
        accepted_values: ['Accepted'],
        min_open_items: 2,                         // don't burn a call on someone who is nearly done…
        min_started_items: 1,                      // …or on someone who never engaged at all
        checklist: [
          { label: 'Identity document', any_of: ['Passport_Status', 'ID_Card_Status', 'Driving_Licence_Status'] },
          { label: 'Right to work', field: 'Right_To_Work_Status', exempt_if: [{ field: 'Residency', values: ['Citizen'] }] },
          { label: 'Background check', field: 'Background_Check_Status' },
          { label: 'Business registration', field: 'Business_Registration_Status',
            label_by: { field: 'Registration_Progress', map: { Obtained: 'Upload business registration', Requested: 'Business registration pending' }, default: 'Register your business' } },
          { label: 'Profile photo', field: 'Profile_Photo_Status' },
          { label: 'Onboarding quiz', field: 'Onboarding_Quiz_Result', accepted_values: [1, '1', 'Passed'] },
        ],
      },
      cascade: { touch_offsets_days: [0, 3, 7], skip_weekends: true, send_hour: 11 },
      retry: { enabled: true, retry_on: ['Voicemail', 'No answer', 'Failed'], max_retries: 1, delay_minutes: 240 },
      kpi: { enabled: true, success_outcomes: ['completed', 'confirmed'] },
    },

    appointment_reminder: {
      label: 'Appointment Reminder',
      agent_id: env('AGENT_REMINDER', 'REPLACE_ME'),
      timezone: 'Europe/Paris', locale: 'fr-FR', default_country_code: '33',
      booking: { enabled: false },
      ab_test: { enabled: false },
      eligibility: null,
      retry: { enabled: false },
      kpi: { enabled: true, success_outcomes: ['confirmed'], realization: { field: 'Session_Attended', truthy: ['Yes', true] } },
    },
  },
};

return [{ json: CONFIG }];
